import React from "react";
import AdoptionInfoHeader from "./components/AdoptionInfoHeader/AdoptionInfoHeader";
import FirstAdoptionInfoContainer from "./components/FirstAdoptionInfoContainer/FirstAdoptionInfoContainer";
import SecondAdoptionInfoContainer from "./components/SecondAdoptionInfoContainer/SecondAdoptionInfoContainer";
import ThirdAdoptionInfoContainer from "./components/ThirdAdoptionInfoContainer/ThirdAdoptionInfoContainer";

const App = () => {
  return (
    <div>
      <AdoptionInfoHeader />
      <FirstAdoptionInfoContainer />
      <SecondAdoptionInfoContainer />
      <ThirdAdoptionInfoContainer />
    </div>
  );
};

export default App;
